  _getStationBannerMat(key, {
    brand = 'WHOOSH',
    title = 'STASIUN HALIM',
    subtitle = 'KERETA CEPAT JAKARTA–BANDUNG • KCIC',
    bgTop = '#0f172a',
    bgBot = '#1e293b',
    accent = '#dc2626',
    subColor = '#fde047'
  } = {}) {
    if (!this.bannerMatCache.has(key)) {
      if (typeof document === 'undefined') {
        this.bannerMatCache.set(key, this.roofDarkMat);
      } else {
        const c = document.createElement('canvas');
        c.width = 1024;
        c.height = 224;
        const ctx = c.getContext('2d');
        const g = ctx.createLinearGradient(0, 0, 0, 224);
        g.addColorStop(0, bgTop);
        g.addColorStop(1, bgBot);
        ctx.fillStyle = g;
        ctx.fillRect(0, 0, 1024, 224);
        ctx.fillStyle = accent;
        ctx.fillRect(0, 0, 1024, 48);
        ctx.fillStyle = '#facc15';
        ctx.fillRect(0, 48, 1024, 5);
        ctx.fillStyle = '#ffffff';
        ctx.font = '900 26px Inter, sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(brand, 512, 34);
        ctx.fillStyle = '#ffffff';
        ctx.font = '900 58px Inter, sans-serif';
        ctx.fillText(title, 512, 134);
        ctx.fillStyle = subColor;
        ctx.font = 'bold 21px JetBrains Mono, monospace';
        ctx.fillText(subtitle, 512, 188);
        ctx.strokeStyle = 'rgba(248, 250, 252, 0.45)';
        ctx.lineWidth = 6;
        ctx.strokeRect(4, 4, 1016, 216);
        const tex = new THREE.CanvasTexture(c);
        tex.colorSpace = THREE.SRGBColorSpace;
        const face = new THREE.MeshBasicMaterial({ map: tex });
        const rim = this.roofDarkMat;
        this.bannerMatCache.set(key, {
          sideX: [face, face, rim, rim, rim, rim],
          sideZ: [rim, rim, rim, rim, face, face]
        });
      }
    }
    return this.bannerMatCache.get(key);
  }
  _getCarZoneMat(carNum) {
    if (!this.carZoneMatCache.has(carNum)) {
      if (typeof document === 'undefined') {
        this.carZoneMatCache.set(carNum, new THREE.MeshBasicMaterial({ color: 0x0284c7 }));
      } else {
        const c = document.createElement('canvas');
        c.width = 256;
        c.height = 64;
        const ctx = c.getContext('2d');
        const isBiz = carNum === 1;
        const isFirst = carNum === 2;
        const isDining = carNum === 5;
        ctx.fillStyle = '#090f1d';
        ctx.fillRect(0, 0, 256, 64);
        ctx.strokeStyle = isFirst ? '#f59e0b' : (isBiz ? '#f43f5e' : '#38bdf8');
        ctx.lineWidth = 4;
        ctx.strokeRect(2, 2, 252, 60);
        ctx.fillStyle = isFirst ? '#f59e0b' : (isBiz ? '#dc2626' : '#0284c7');
        ctx.fillRect(6, 6, 92, 52);
        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(`CAR ${carNum}`, 52, 41);
        ctx.fillStyle = '#e2e8f0';
        ctx.font = 'bold 14px sans-serif';
        const roleTxt = isBiz
          ? 'BUSINESS CLASS'
          : (isFirst ? 'FIRST CLASS VIP' : (isDining ? 'MINIBAR • ECO' : 'PREMIUM ECO'));
        ctx.fillText(roleTxt, 174, 28);
        ctx.fillStyle = '#fde047';
        ctx.font = 'bold 11px monospace';
        ctx.fillText(`KERETA 0${carNum} • ANTRE PERON`, 174, 48);
        const tex = new THREE.CanvasTexture(c);
        tex.colorSpace = THREE.SRGBColorSpace;
        const rim = this.roofDarkMat;
        const face = new THREE.MeshBasicMaterial({ map: tex });
        this.carZoneMatCache.set(carNum, [face, face, rim, rim, rim, rim]);
      }
    }
    return this.carZoneMatCache.get(carNum);
  }
  updatePlatformPIDSTexture({
    clockStr = '07:30',
    trainNo = 'G1215',
    destName = 'TEGALLUAR',
    statusText = 'TEPAT WAKTU',
    isExpress = false
  } = {}) {
    if (!this.platformPidsCtx || !this.platformPidsTex) return;
    const key = `${clockStr}|${trainNo}|${destName}|${statusText}|${isExpress ? 1 : 0}`;
    if (key === this._lastPidsKey) return;
    this._lastPidsKey = key;
    const ctx = this.platformPidsCtx;
    ctx.fillStyle = '#040812';
    ctx.fillRect(0, 0, 512, 128);
    ctx.strokeStyle = '#1e293b';
    ctx.lineWidth = 4;
    ctx.strokeRect(2, 2, 508, 124);
    ctx.fillStyle = '#991b1b';
    ctx.fillRect(4, 4, 376, 26);
    ctx.fillStyle = '#0f172a';
    ctx.fillRect(380, 4, 128, 26);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 14px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('WHOOSH KCIC • JADWAL PERON KEBERANGKATAN', 12, 22);
    ctx.fillStyle = '#38bdf8';
    ctx.font = 'bold 15px monospace';
    ctx.textAlign = 'right';
    ctx.fillText(`${clockStr} WIB`, 500, 22);
    ctx.textAlign = 'left';
    ctx.fillStyle = '#fde047';
    ctx.font = 'bold 20px monospace';
    ctx.fillText(trainNo, 12, 58);
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 19px sans-serif';
    ctx.fillText(destName.slice(0, 14), 96, 58);
    ctx.fillStyle = isExpress ? '#f59e0b' : '#38bdf8';
    ctx.font = 'bold 13px monospace';
    ctx.fillText(isExpress ? 'EXPRESS 350' : 'CAR 1 - 8', 250, 57);
    ctx.fillStyle = statusText.includes('BOARDING') ? '#10b981' : '#34d399';
    ctx.font = 'bold 14px monospace';
    ctx.fillText(statusText.slice(0, 20), 348, 57);
    ctx.fillStyle = '#94a3b8';
    ctx.font = 'bold 16px monospace';
    ctx.fillText('G1223', 12, 86);
    ctx.fillStyle = '#cbd5e1';
    ctx.font = 'bold 15px sans-serif';
    ctx.fillText(destName === 'HALIM JAKARTA' ? 'TEGALLUAR' : 'HALIM JAKARTA', 96, 86);
    ctx.fillStyle = '#38bdf8';
    ctx.font = 'bold 13px monospace';
    ctx.fillText('CAR 1 - 8', 250, 86);
    ctx.fillStyle = '#f59e0b';
    ctx.fillText('PERSIAPAN CONCOURSE', 348, 86);
    ctx.fillStyle = '#0c192c';
    ctx.fillRect(4, 98, 504, 26);
    ctx.fillStyle = '#fde047';
    ctx.font = 'bold 12px monospace';
    ctx.fillText('CAR 1: BISNIS • CAR 2: FIRST VIP • CAR 3-8: PREMIUM ECO • CAR 5: MINIBAR', 12, 115);
    this.platformPidsTex.needsUpdate = true;
  }
  _getRockShellMat(hexColor) {
    if (!this.rockMatCache.has(hexColor)) {
      this.rockMatCache.set(
        hexColor,
        new THREE.MeshStandardMaterial({
          color: hexColor,
          roughness: 0.92,
          side: THREE.DoubleSide
        })
      );
    }
    return this.rockMatCache.get(hexColor);
  }
  _getStationFacadeMat(stName) {
    if (!this.facadeMatCache.has(stName)) {
      const tex = ProceduralAssetFactory.createStationFacadeTexture(stName);
      this.facadeMatCache.set(
        stName,
        new THREE.MeshStandardMaterial({
          map: tex,
          roughness: 0.25,
          metalness: 0.55,
          envMapIntensity: 1.25
        })
      );
    }
    return this.facadeMatCache.get(stName);
  }
  _getStationSignMat(stName, elevM, dkLabel) {
    const key = `${stName}_${elevM}_${dkLabel}`;
    if (!this.signMatCache.has(key)) {
      const tex = ProceduralAssetFactory.createStationSignTexture(stName, elevM, dkLabel);
      this.signMatCache.set(
        key,
        new THREE.MeshBasicMaterial({ map: tex, side: THREE.DoubleSide })
      );
    }
    return this.signMatCache.get(key);
  }
  _getTunnelPortalSignMat(tunnelId) {
    const id = tunnelId || 1;
    if (!this.tunnelSignMatCache.has(id)) {
      const info = GAME_PREMISE_CARTRIDGE.tunnels[id] || { id, name: `Tunnel #${id}`, lengthM: 1200 };
      const tex = ProceduralAssetFactory.createTunnelPortalSignTexture(info);
      const faceMat = new THREE.MeshBasicMaterial({ map: tex });
      const rimMat = this.roofDarkMat;
      this.tunnelSignMatCache.set(id, [rimMat, rimMat, rimMat, rimMat, faceMat, rimMat]);
    }
    return this.tunnelSignMatCache.get(id);
  }
