        const nz = pos.getZ(i);
        const jawTaper = ny < 0.08
          ? (1.0 - 0.35 * Math.pow(Math.min(1, (0.08 - ny) / 1.08), 1.48))
          : (1.0 - 0.07 * Math.pow(Math.max(0, ny - 0.52) / 0.48, 1.55));
