  _initWorker() {
    this.worker = null;
    try {
      const inlineBlobUrl = typeof globalThis !== 'undefined' && globalThis.__WHOOSH_WORKER_BLOB__
        ? globalThis.__WHOOSH_WORKER_BLOB__
        : null;
      this.worker = inlineBlobUrl
        ? new Worker(inlineBlobUrl)
        : new Worker(new URL('../workers/ChunkBuilderWorker.js', import.meta.url), { type: 'module' });
      this.worker.onmessage = (e) => {
        const msg = e.data;
        if (!msg) return;
        if (msg.type === 'CHUNK_READY' && msg.data) {
          this.pendingChunks.delete(msg.data.chunkIdx);
          if (!this.chunks.has(msg.data.chunkIdx)) {
            this.completedQueue.push(msg.data);
          }
        } else if (msg.type === 'CHUNK_ERROR') {
          this.pendingChunks.delete(msg.chunkIdx);
        }
      };
      this.worker.onerror = () => {
        this.worker = null;
        this.pendingChunks.clear();
      };
      const { wasmBytes, vaultBytes } = WasmRouteKernel.getRawBuffers();
      if (wasmBytes && vaultBytes) {
        const host = (typeof window !== 'undefined' && window.location) ? window.location.hostname : 'localhost';
        this.worker.postMessage({
          type: 'INIT_VAULT',
          wasmBytes: wasmBytes.slice(),
          vaultBytes: vaultBytes.slice(),
          host
        });
      }
    } catch (_) {
      this.worker = null;
    }
  }
  warmupInitialChunks(initialS, floatingOrigin = EndlessWorldMathematics.floatingOrigin, fastBoot = false) {
    const chunkLen = GAME_PREMISE_CARTRIDGE.railway.chunkLength;
    const maxChunk = Math.ceil(GAME_PREMISE_CARTRIDGE.railway.totalRouteLength / chunkLen);
    const curIdx = Math.floor(initialS / chunkLen);
    const backSpan = fastBoot ? 1 : 2;
    const fwdSpan = fastBoot ? 2 : 5;
    for (let idx = Math.max(0, curIdx - backSpan); idx <= Math.min(maxChunk - 1, curIdx + fwdSpan); idx++) {
      if (!this.chunks.has(idx)) {
        const data = ChunkGeometryCore.buildChunkBuffers(idx);
        const grp = this.assembleChunkFromBuffers(data, floatingOrigin);
        this.chunks.set(idx, grp);
        this.scene.add(grp);
      }
    }
  }
  applyOriginRebase(floatingOrigin = EndlessWorldMathematics.floatingOrigin) {
    const ox = floatingOrigin.originX;
    const oy = floatingOrigin.originY;
    const oz = floatingOrigin.originZ;
    for (const group of this.chunks.values()) {
      group.position.set(
        group.userData.anchorX - ox,
        group.userData.anchorY - oy,
        group.userData.anchorZ - oz
      );
    }
    if (this.farCorridorGroup) {
      this.farCorridorGroup.position.set(
        this.farCorridorGroup.userData.anchorX - ox,
        this.farCorridorGroup.userData.anchorY - oy,
        this.farCorridorGroup.userData.anchorZ - oz
      );
    }
  }
  setTunnelOcclusion(occ = 0.0) {
    this._tunnelOcc = occ;
    if (this.farCorridorGroup) {
      this.farCorridorGroup.visible = occ < 0.72;
    }
  }
  setEnvMap(envMap) {
    this.envMap = envMap;
  }
  setNightFactor(nightFactor = 0.0, timeSec = 0.0) {
    const nf = THREE.MathUtils.clamp(nightFactor, 0.0, 1.0);
    if (this.buildingFacadeMats) {
      for (let i = 0; i < this.buildingFacadeMats.length; i++) {
        this.buildingFacadeMats[i].emissiveIntensity = nf * 0.96;
      }
    }
    if (this.chunkNightGlowMat) {
      this.chunkNightGlowMat.opacity = nf;
      this.chunkNightGlowMat.visible = nf > 0.01;
    }
    if (this.alJabbarDynamicMat) {
      this.alJabbarDynamicMat.opacity = nf * 0.88;
      this.alJabbarDynamicMat.visible = nf > 0.01;
      if (nf > 0.01) {
        const hue = (0.40 + 0.46 * (0.5 + 0.5 * Math.sin(timeSec * 0.36))) % 1.0;
        this.alJabbarDynamicMat.color.setHSL(hue, 0.88, 0.58);
      }
    }
  }
