      pdaGrp.position.set(0.01, -0.24, 0.14);
      pdaGrp.rotation.x = -0.52;
      const pdaShell = new THREE.Mesh(PPG.pdaScanner, CM.pdaBody);
      pdaShell.userData.sharedGeo = true;
      const pdaGlow = new THREE.Mesh(PPG.pdaScreen, CM.pdaLaser);
      pdaGlow.userData.sharedGeo = true;
