  _disposeGroupNonShared(grp) {
    while (grp.children.length > 0) {
      const child = grp.children[0];
      grp.remove(child);
      child.traverse((o) => {
        if (o.geometry && !o.userData.sharedGeo && !o.geometry.userData?.sharedGeo) {
          o.geometry.dispose();
        }
      });
    }
  }
