    const makePneumaticDialMat = (labelTxt, subTxt, highlightBarA, highlightBarB) => {
      if (typeof document === 'undefined') return new THREE.MeshBasicMaterial({ color: 0x0f172a });
      const dc = document.createElement('canvas');
      dc.width = 256;
      dc.height = 256;
      const dctx = dc.getContext('2d');
      dctx.fillStyle = '#0b1220';
      dctx.beginPath();
      dctx.arc(128, 128, 124, 0, Math.PI * 2);
      dctx.fill();
      dctx.strokeStyle = '#334155';
      dctx.lineWidth = 6;
      dctx.stroke();
      const angStart = Math.PI * 0.75;
      const angSpan = Math.PI * 1.5;
      dctx.strokeStyle = 'rgba(16, 185, 129, 0.45)';
      dctx.lineWidth = 10;
      dctx.beginPath();
      dctx.arc(128, 128, 104, angStart + ((highlightBarA - 0.5) / 12) * angSpan, angStart + ((highlightBarA + 0.6) / 12) * angSpan);
      dctx.stroke();
      dctx.strokeStyle = 'rgba(239, 68, 68, 0.55)';
      dctx.beginPath();
      dctx.arc(128, 128, 104, angStart + (highlightBarB / 12) * angSpan, angStart + angSpan);
      dctx.stroke();
      dctx.font = 'bold 17px JetBrains Mono, monospace';
      dctx.textAlign = 'center';
      dctx.textBaseline = 'middle';
      for (let b = 0; b <= 24; b++) {
        const barVal = b * 0.5;
        const ang = angStart + (barVal / 12) * angSpan;
        const isMajor = (b % 4 === 0);
        const isMid = (b % 2 === 0);
        const rIn = isMajor ? 82 : (isMid ? 90 : 96);
        dctx.strokeStyle = barVal >= highlightBarB ? '#f87171' : (Math.abs(barVal - highlightBarA) < 0.3 ? '#34d399' : '#e2e8f0');
        dctx.lineWidth = isMajor ? 4 : (isMid ? 2.4 : 1.4);
        dctx.beginPath();
        dctx.moveTo(128 + Math.cos(ang) * rIn, 128 + Math.sin(ang) * rIn);
        dctx.lineTo(128 + Math.cos(ang) * 108, 128 + Math.sin(ang) * 108);
        dctx.stroke();
        if (isMajor) {
          dctx.fillStyle = barVal >= highlightBarB ? '#fca5a5' : '#f8fafc';
          dctx.fillText(String(barVal), 128 + Math.cos(ang) * 65, 128 + Math.sin(ang) * 65);
        }
      }
      dctx.fillStyle = '#38bdf8';
      dctx.font = 'bold 18px JetBrains Mono, monospace';
      dctx.fillText(labelTxt, 128, 174);
      dctx.fillStyle = '#94a3b8';
      dctx.font = 'bold 14px JetBrains Mono, monospace';
      dctx.fillText(subTxt, 128, 196);
      const dTex = new THREE.CanvasTexture(dc);
      dTex.colorSpace = THREE.SRGBColorSpace;
      return new THREE.MeshBasicMaterial({ map: dTex });
    };
